INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('0318f1d7-7a3b-433a-858b-327c354548a9','zh-CN','我兒，神必自己預備作燔祭的羊羔','创世记 22:8','以撒问燔祭的羊羔在哪里，亚伯拉罕如此回答。','CUV-1919','han-traditional','source_verified','80c59700c09ce656003dc3b9bb3d8b368415457033658ecd2d6d3d6803005228','亞伯拉罕說：「我兒，神必自己預備作燔祭的羊羔。」於是二人同行。','f57ea7e683b8e4923522bc79b87f84202607d3c5856fde141753f14b579e3217','https://bible-api.com/data/cuv/GEN/22/8','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('0318f1d7-7a3b-433a-858b-327c354548a9','en','God will provide himself the lamb for a burnt offering, my son','Genesis 22:8','His answer when Isaac asks where the lamb is.','WEB','na','source_verified','f647f4880dbd472170fbb7a8b9ff80258072ad6c5688c6876a14117a346e2b70','Abraham said, “God will provide himself the lamb for a burnt offering, my son.” So they both went together.','9448b2ad191257bc92fa876214dfed31a147473730095a8c153f6845f4a5b9ca','https://bible-api.com/data/web/GEN/22/8','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('1bbc6e57-d45d-4ec1-86a8-41babc54b57c','43000000-0000-4000-8001-000000000001','10000000-0000-4000-8000-000000000005','63000000-0000-4000-8001-000000000009','Gen.3.12','admission',4,2)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('1bbc6e57-d45d-4ec1-86a8-41babc54b57c','zh-CN','你所賜給我、與我同居的女人，她把那樹上的果子給我，我就吃了','创世记 3:12','被追问时的第一句推诿。','CUV-1919','han-traditional','source_verified','b13b4d2c06d078335cec86b6946000f3726abb6f1969af15c7c3abf2498dbe8b','那人說：「你所賜給我、與我同居的女人，她把那樹上的果子給我，我就吃了。」','5088137e825c65ea12bb8c36a13fe50416089ca906a9411fac88dea6d73306a0','https://bible-api.com/data/cuv/GEN/3/12','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('1bbc6e57-d45d-4ec1-86a8-41babc54b57c','en','The woman whom you gave to be with me, she gave me fruit from the tree, and I ate','Genesis 3:12','The first deflection in the garden interrogation.','WEB','na','source_verified','4adaa95bf4cd6aba80a1a54b3da5cfe819820ab102a2aaf936566470c11fa14d','The man said, “The woman whom you gave to be with me, she gave me fruit from the tree, and I ate it.”','84036a626c6d3583f287bde3cbfff0c7a585c9331fde99aa576666770663fcc8','https://bible-api.com/data/web/GEN/3/12','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('0689ab45-aa1d-4a88-86fc-bba8f7552e7a','43000000-0000-4000-8001-000000000002','10000000-0000-4000-8000-000000000005','63000000-0000-4000-8001-000000000009','Gen.3.13','admission',4,3)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('0689ab45-aa1d-4a88-86fc-bba8f7552e7a','zh-CN','那蛇引誘我，我就吃了','创世记 3:13','紧接亚当之后的回答。','CUV-1919','han-traditional','source_verified','4d2004cd32fcf0ebe8087256635bcb2b04efa90b2752fa64b7b6cbb69f2878cf','耶和華神對女人說：「你作的是甚麼事呢？」女人說：「那蛇引誘我，我就吃了。」','c7b185770ea8b397777a83ef8c8e8b02601c7b28705353c5324180d6f0dc2e65','https://bible-api.com/data/cuv/GEN/3/13','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('0689ab45-aa1d-4a88-86fc-bba8f7552e7a','en','The serpent deceived me, and I ate','Genesis 3:13','Her answer immediately after Adam''s.','WEB','na','source_verified','aa1b0214136a08c3de04c0ae4f956a40a84558f4e510453fac60519d42a17427','Yahweh God said to the woman, “What have you done?” The woman said, “The serpent deceived me, and I ate.”','9b948c7ce1eb9d89174fe11298f6543c863bc231ae4ee3d41c37eaf7df31b8b0','https://bible-api.com/data/web/GEN/3/13','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('6498e60e-ba6b-4c02-8759-500db8746761','21000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000005','62000000-0000-4000-8000-000000000012','Gen.28.16','declaration',5,4)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('6498e60e-ba6b-4c02-8759-500db8746761','zh-CN','耶和華真在這裏，我竟不知道','创世记 28:16','伯特利梦醒后的第一句话。','CUV-1919','han-traditional','source_verified','085787183ef1e7e3a87321ec541bb41fd91a9a6388df7499e87ed51418a45ce4','雅各睡醒了，說：「耶和華真在這裏，我竟不知道！」','6f00e534b028549406f2df92bfffe9559992c40ea27557534d1548999e631225','https://bible-api.com/data/cuv/GEN/28/16','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('6498e60e-ba6b-4c02-8759-500db8746761','en','Surely Yahweh is in this place, and I didn’t know it','Genesis 28:16','His first words on waking at Bethel.','WEB','na','source_verified','c67942b080d675ee99e352ab0bc56ad799ff6e3830e6ade0f5a5ad1ba9d8dcf1','Jacob awakened out of his sleep, and he said, “Surely Yahweh is in this place, and I didn’t know it.”','39f2be1a74b939e8839ae0ab75b9de137e8ae97a264c8f30eb17af168ec2ed1e','https://bible-api.com/data/web/GEN/28/16','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('97cd7027-2356-474f-8841-4569a72cbd34','42000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000005',NULL,'Gen.50.20','declaration',5,5)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('97cd7027-2356-474f-8841-4569a72cbd34','zh-CN','從前你們的意思是要害我，但神的意思原是好的','创世记 50:20','与兄弟重逢并赦免时所说。','CUV-1919','han-traditional','source_verified','475b96afb2b3c48fb998309bcdef77c8c1eca962ffd6c74d94dd22bdceef9f12','從前你們的意思是要害我，但神的意思原是好的，要保全許多人的性命，成就今日的光景。','bb254326a6940e5265bb87ee1bb2a3dff43b2ad1a0b2bffe1377dfd130a9ccc3','https://bible-api.com/data/cuv/GEN/50/20','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('97cd7027-2356-474f-8841-4569a72cbd34','en','As for you, you meant evil against me, but God meant it for good','Genesis 50:20','Spoken when he forgives his brothers.','WEB','na','source_verified','93073f2b618c6bf8703b1be934c88083be68653db5cf996cd579782cd6d0b9ef','As for you, you meant evil against me, but God meant it for good, to bring to pass, as it is today, to save many people alive.','f2e07e4566bb763e665c157c1f6daf7bf92b697964b6c5080bd32e4ab49604ea','https://bible-api.com/data/web/GEN/50/20','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('60adc7ab-f1e8-4a44-802f-36f1892e05a6','21000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005',NULL,'Exod.5.1','command',5,6)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('60adc7ab-f1e8-4a44-802f-36f1892e05a6','zh-CN','容我的百姓去，在曠野向我守節','出埃及记 5:1','首次面见法老时转述的话。','CUV-1919','han-traditional','source_verified','922288491fc9b0555bba14df91f0dae0cce596ffa9a7867a9a3a1319a1935775','後來摩西、亞倫去對法老說：「耶和華以色列的神這樣說：『容我的百姓去，在曠野向我守節。』」','5e1023a9ab5f646f5c31e64a3a6c5f075038ee8a7abea9a666f9d788173490fe','https://bible-api.com/data/cuv/EXO/5/1','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('60adc7ab-f1e8-4a44-802f-36f1892e05a6','en','Let my people go, that they may hold a feast to me in the wilderness','Exodus 5:1','The message he carries to Pharaoh.','WEB','na','source_verified','aa133bd17573427f529cf4a6ca12ea631e3cf33f19312fb60bae07d4aa6bc4f5','Afterward Moses and Aaron came, and said to Pharaoh, “This is what Yahweh, the God of Israel, says, ‘Let my people go, that they may hold a feast to me in the wilderness.’”','62f245c5a6746f1f5b0e27505eaa07c888217338c2b3b9717c9417cc9250ec57','https://bible-api.com/data/web/EXO/5/1','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('2c34eeb1-d501-4f26-8cbc-128d576408db','21000000-0000-4000-8000-000000000005','10000000-0000-4000-8000-000000000005',NULL,'Deut.6.4','declaration',5,7)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('2c34eeb1-d501-4f26-8cbc-128d576408db','zh-CN','以色列啊，你要聽','申命记 6:4','示玛（Shema）的开篇。','CUV-1919','han-traditional','source_verified','84869bf3899c3661813901559805b506a558da169dffc4110ad7bfc820b7a089','「以色列啊，你要聽！耶和華我們神是獨一的主。','b9572cc851669f7e3fb90d82c83412bcd982693e39db8b8fb39d96ae3366a180','https://bible-api.com/data/cuv/DEU/6/4','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('2c34eeb1-d501-4f26-8cbc-128d576408db','en','Hear, Israel','Deuteronomy 6:4','The opening of the Shema.','WEB','na','source_verified','3c9401700ed6442b74a4ecc9b8f455004799c8183d387190df7f27b21283ff28','Hear, Israel: Yahweh is our God. Yahweh is one.','7e105bfbeb9b106f639827c088445bb14be21ce8aaa4a4bb332f48fbf6b3677f','https://bible-api.com/data/web/DEU/6/4','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('aafb4f6f-d1aa-4851-8867-ccefb9884872','42000000-0000-4000-8000-000000000012','10000000-0000-4000-8000-000000000005',NULL,'Exod.15.21','praise',3,8)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('aafb4f6f-d1aa-4851-8867-ccefb9884872','zh-CN','你們要歌頌耶和華，因他大大戰勝','出埃及记 15:21','过海之后领众妇女击鼓歌唱。','CUV-1919','han-traditional','source_verified','2cde8721b3bae38eeaa200c4ebc4cb2cf39699d15764f47f41361649c6f43ae2','米利暗應聲說：你們要歌頌耶和華，因他大大戰勝，將馬和騎馬的投在海中。','fc68bb99bd3b00f47a69c31f35e5df1467469498c08cf96524c435b2659d66bf','https://bible-api.com/data/cuv/EXO/15/21','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('aafb4f6f-d1aa-4851-8867-ccefb9884872','en','Sing to Yahweh, for he has triumphed gloriously','Exodus 15:21','Her song with the women after the sea crossing.','WEB','na','source_verified','0c883d232936879924eb12a3b1c19fbfea003c2609f1cd1dce298a6d7d257ab8','Miriam answered them, “Sing to Yahweh, for he has triumphed gloriously. The horse and his rider he has thrown into the sea.”','b0a8a1d44209074d02dd7e2cf3248df256b6c30ed78440a4d4a358acd214588e','https://bible-api.com/data/web/EXO/15/21','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('ade61cfe-f972-449e-8453-9cba929af6f1','21000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000005',NULL,'Gen.18.12','question',3,9)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('ade61cfe-f972-449e-8453-9cba929af6f1','zh-CN','我既已衰敗，我主也老邁，豈能有這喜事呢','创世记 18:12','在帐棚门口听见应许后暗笑所说，与她的帐棚徽章互文。','CUV-1919','han-traditional','source_verified','517b91d9793d4d9b1ca53328610fb0718e6904251c0bfa68d68fc20d7c153387','撒拉心裏暗笑，說：「我既已衰敗，我主也老邁，豈能有這喜事呢？」','2eae9b3ec9ba868487fb717e0c3d3a1c08fbafca7cad9a2e7293702ea8b8c86d','https://bible-api.com/data/cuv/GEN/18/12','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('ade61cfe-f972-449e-8453-9cba929af6f1','en','After I have grown old will I have pleasure, my lord being old also','Genesis 18:12','Spoken to herself, laughing, when she overhears the promise at the tent door — the scene her emblem records.','WEB','na','source_verified','5330d33d3bdc666d97160e84f19364234022367a7004c2245e85e25ff73f29c0','Sarah laughed within herself, saying, “After I have grown old will I have pleasure, my lord being old also?”','676ff10589554e5b6cad402793c997dfdd8e73be89e1760864e8e8842d0e9fcc','https://bible-api.com/data/web/GEN/18/12','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('9098d4e3-1510-4eca-844c-a3d5abf5df84','43000000-0000-4000-8005-000000000008','10000000-0000-4000-8000-000000000005',NULL,'1Sam.2.1','praise',4,10)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('9098d4e3-1510-4eca-844c-a3d5abf5df84','zh-CN','我的心因耶和華快樂','撒母耳记上 2:1','献上撒母耳后的祷告开篇；其结构与措辞是路加福音尊主颂的先声。','CUV-1919','han-traditional','source_verified','c672ac3158e1679dcfb1b4e33b8ce306c61715271ffbf5c3a14a2693fd401890','哈拿禱告說：我的心因耶和華快樂；我的角因耶和華高舉。我的口向仇敵張開；我因耶和華的救恩歡欣。','ab28e6ecdddb68ce192ffc4551d542cfa7b0a6355c12481117156879c96138b5','https://bible-api.com/data/cuv/1SA/2/1','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('9098d4e3-1510-4eca-844c-a3d5abf5df84','en','My heart exults in Yahweh','1 Samuel 2:1','The opening of her prayer after she gives up Samuel; its shape and wording stand behind the Magnificat in Luke.','WEB','na','source_verified','2847596b140b24b855f880a2ab5cf4e2e7fcddc69345d2d08fcae73eefb63989','Hannah prayed, and said: “My heart exults in Yahweh! My horn is exalted in Yahweh. My mouth is enlarged over my enemies, because I rejoice in your salvation.','25f57e6d972454250f7d9dc97f7e43c18324e378c3e08eefdbfacb04bae8f629','https://bible-api.com/data/web/1SA/2/1','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('6b6a6f9e-0fce-415c-8481-3037752467e8','42000000-0000-4000-8000-000000000015','10000000-0000-4000-8000-000000000005',NULL,'Josh.24.15','declaration',5,11)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('6b6a6f9e-0fce-415c-8481-3037752467e8','zh-CN','至於我和我家，我們必定事奉耶和華','约书亚记 24:15','示剑大会上要求百姓选择时所说。','CUV-1919','han-traditional','source_verified','ffad558f55f145601a935094b0a80e9961b6f6b420494b50f4e5d833e81dfcca','若是你們以事奉耶和華為不好，今日就可以選擇所要事奉的：是你們列祖在大河那邊所事奉的神呢？是你們所住這地的亞摩利人的神呢？至於我和我家，我們必定事奉耶和華。」','d8cd173c7bf8a02f15e8a749e0b1b704bfccc42b04c3e92f67d02105a850b6f5','https://bible-api.com/data/cuv/JOS/24/15','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('6b6a6f9e-0fce-415c-8481-3037752467e8','en','as for me and my house, we will serve Yahweh','Joshua 24:15','At the assembly of Shechem, calling for a choice.','WEB','na','source_verified','2ce1bf28617772568e78f3d76050577fd44d9f5a69bd8c69819a3fbd17cc5847','If it seems evil to you to serve Yahweh, choose today whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell; but as for me and my house, we will serve Yahweh.”','c99da1a9450f249c9277eef6a3ed91643dc4c12b89ca48e3d15c0117d7a80d90','https://bible-api.com/data/web/JOS/24/15','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('32bf324c-f180-4c18-83f9-e906f0029f25','42000000-0000-4000-8000-000000000018','10000000-0000-4000-8000-000000000005',NULL,'Judg.5.7','declaration',3,12)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('32bf324c-f180-4c18-83f9-e906f0029f25','zh-CN','直到我底波拉興起','士师记 5:7','底波拉之歌中的自述；她此前有棕树徽章却不出声。','CUV-1919','han-traditional','source_verified','5dea1c2c250d0cfe106124b08aa74c37f3445f6887ae28d3d3510c1236040f24','以色列中的官長停職，直到我底波拉興起，等我興起作以色列的母。','41617ddfce9bcb5c79c65d34122563dd00d88292f8838013fd4d34d0486f1ab3','https://bible-api.com/data/cuv/JDG/5/7','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('32bf324c-f180-4c18-83f9-e906f0029f25','en','until I, Deborah, arose','Judges 5:7','From the Song of Deborah; until now she carried a palm emblem in this atlas but no voice.','WEB','na','source_verified','e67dd74355bba44ef8f7c2ea3785d19132596834d59741e1aeba5cf127dfd0ee','The rulers ceased in Israel. They ceased until I, Deborah, arose; Until I arose a mother in Israel.','490a46578cd7ec1d87e3aa3998d347401670c27da6b0b0a0ccb6fabcd3586dec','https://bible-api.com/data/web/JDG/5/7','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('eac07fbb-2343-46f9-8f80-5a491e5a88f1','42000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000005',NULL,'Judg.6.15','objection',3,13)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('eac07fbb-2343-46f9-8f80-5a491e5a88f1','zh-CN','我有何能拯救以色列人呢','士师记 6:15','受召时的推辞。','CUV-1919','han-traditional','source_verified','40fe4136cc13bee1de6bb4be2fa616a9a8abd4e31e49a538e39900b30aeca6b3','基甸說：「主啊，我有何能拯救以色列人呢？我家在瑪拿西支派中是至貧窮的。我在我父家是至微小的。」','4da9f0d67a44403bd1c04a788e9f765662532fc40392cf473464f7c4fa50c082','https://bible-api.com/data/cuv/JDG/6/15','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('eac07fbb-2343-46f9-8f80-5a491e5a88f1','en','how shall I save Israel','Judges 6:15','His objection when called.','WEB','na','source_verified','91c04cb0e3265a5dce0de97b98da74e771d467646cc1c08381267436a9e5b87c','He said to him, “O Lord, how shall I save Israel? Behold, my family is the poorest in Manasseh, and I am the least in my father’s house.”','537e3bb7c96409181f0ac17db2c84734742b1283f5e1d522aff0981b51d626ac','https://bible-api.com/data/web/JDG/6/15','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('9f8b948b-74fe-4482-8b7f-394b4b9e531d','42000000-0000-4000-8000-000000000021','10000000-0000-4000-8000-000000000005',NULL,'Judg.16.30','declaration',3,14)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('9f8b948b-74fe-4482-8b7f-394b4b9e531d','zh-CN','我情願與非利士人同死','士师记 16:30','推倒柱子前的最后一句。','CUV-1919','han-traditional','source_verified','62ec5f865a2f7e4ed3946b351fdc56bdcddf9bb1dc151e59cb693376d6c2dade','說：「我情願與非利士人同死！」就盡力屈身，房子倒塌，壓住首領和房內的眾人。這樣，參孫死時所殺的人比活着所殺的還多。','d76ef170d99ad2fd63ac6a61438a89089908efa939e08036955fcbd6949ca10d','https://bible-api.com/data/cuv/JDG/16/30','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('9f8b948b-74fe-4482-8b7f-394b4b9e531d','en','Let me die with the Philistines','Judges 16:30','His last words before the pillars fall.','WEB','na','source_verified','77b1fe53908d82d01071ad8ce7531e970d4f16aec7977e3c4e3845fd0e586844','Samson said, “Let me die with the Philistines!” He bowed himself with all his might; and the house fell on the lords, and on all the people who were therein. So the dead that he killed at his death were more than those who he killed in his life.','ea475698cd7803be93f23236a09cd5784a474e9785d9759afdf8a5d44acb0d80','https://bible-api.com/data/web/JDG/16/30','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('87d942bf-0f20-4e1f-8333-27ae6f404548','42000000-0000-4000-8000-000000000023','10000000-0000-4000-8000-000000000005',NULL,'Ruth.1.16','confession',5,15)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('87d942bf-0f20-4e1f-8333-27ae6f404548','zh-CN','你往那裏去，我也往那裏去','路得记 1:16','拒绝离开拿俄米时的誓言。','CUV-1919','han-traditional','source_verified','0aa6e81b14c8edb200ab0ac9f36349df6ac489b166e39dedf1b15ef14ded54c2','路得說：「不要催我回去不跟隨你。你往那裏去，我也往那裏去；你在那裏住宿，我也在那裏住宿；你的國就是我的國，你的神就是我的神。','1d6552d81bf1a4d62f7275cf8dd5d3e505d662d3a950ba357b491a3cc09a9f15','https://bible-api.com/data/cuv/RUT/1/16','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('87d942bf-0f20-4e1f-8333-27ae6f404548','en','where you go, I will go','Ruth 1:16','Her vow when she refuses to leave Naomi.','WEB','na','source_verified','bac6b16b873fad237e52e9aaa2277e308457d5706ea5eeeaaf8f3a5c90854866','Ruth said, “Don’t urge me to leave you, and to return from following you, for where you go, I will go; and where you stay, I will stay. Your people will be my people, and your God my God.','cbee7ea08c1462a314e28edd826963ea961692732dbdd0c5bd1903273efa090b','https://bible-api.com/data/web/RUT/1/16','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('a377402d-d171-40d7-8ede-3dd3bee45554','42000000-0000-4000-8000-000000000025','10000000-0000-4000-8000-000000000005',NULL,'1Sam.3.10','confession',4,16)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('a377402d-d171-40d7-8ede-3dd3bee45554','zh-CN','請說，僕人敬聽','撒母耳记上 3:10','夜间第四次被呼唤后的回应。','CUV-1919','han-traditional','source_verified','041f30a0cbb642b85c185dcda791c66b286da0861e051c3fff68f859c3b53734','耶和華又來站着，像前三次呼喚說：「撒母耳啊！撒母耳啊！」撒母耳回答說：「請說，僕人敬聽！」','45b91baaa0c37f3b2c8922006096aed91a00b1d2a1e2d3d8c2cf88ed002a99f2','https://bible-api.com/data/cuv/1SA/3/10','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('a377402d-d171-40d7-8ede-3dd3bee45554','en','Speak; for your servant hears','1 Samuel 3:10','His answer at the fourth call in the night.','WEB','na','source_verified','3876dda21388b36ebeb27d0919b3d6008682cab7a9ad22b332ffc8c9dcaa2f2a','Yahweh came, and stood, and called as at other times, “Samuel! Samuel!” Then Samuel said, “Speak; for your servant hears.”','0d07ea6d59613d214af55b0994621a80a7c9bc376e777deb22f9007ff1d17dcc','https://bible-api.com/data/web/1SA/3/10','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('7a2a92c4-3006-4ec6-84c5-078bcfbdaf10','21000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000005',NULL,'1Sam.17.45','declaration',5,17)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('7a2a92c4-3006-4ec6-84c5-078bcfbdaf10','zh-CN','我來攻擊你，是靠着萬軍之耶和華的名','撒母耳记上 17:45','在以拉谷对歌利亚所说。','CUV-1919','han-traditional','source_verified','1fc3de655c84f45dd2aaf6b07e80e153501291095880959c3cfdda93c54fe103','大衛對非利士人說：「你來攻擊我，是靠着刀槍和銅戟；我來攻擊你，是靠着萬軍之耶和華的名，就是你所怒罵帶領以色列軍隊的神。','ed9b00522368e924eabc08a5ebe33ff5df7664abfe17e379716a56eb4ccfb6fc','https://bible-api.com/data/cuv/1SA/17/45','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('7a2a92c4-3006-4ec6-84c5-078bcfbdaf10','en','I come to you in the name of Yahweh of Armies','1 Samuel 17:45','Spoken to Goliath in the Valley of Elah.','WEB','na','source_verified','c625bbb8ec123cb9c49a87ab695e95cdb297f70b5b51a7280a4e8db24dc46128','Then David said to the Philistine, “You come to me with a sword, with a spear, and with a javelin; but I come to you in the name of Yahweh of Armies, the God of the armies of Israel, whom you have defied.','c463071d86b79f5f357fc6f6d653e60258857085a4cd18dd12eab35b1b67ff2c','https://bible-api.com/data/web/1SA/17/45','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('f8e4ae62-d455-474f-8cfb-0d7b53649dde','21000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000005',NULL,'Ps.23.1','prayer',5,18)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('f8e4ae62-d455-474f-8cfb-0d7b53649dde','zh-CN','耶和華是我的牧者，我必不至缺乏','诗篇 23:1','诗篇 23 的开篇，超题归于大卫。','CUV-1919','han-traditional','source_verified','731b1accd6c00656b0c8df362036ae3f9b8e8ed3428dfd7b92b35561a515f586','（大衛的詩）耶和華是我的牧者，我必不至缺乏。','d3cdea755388aeb847a020b19369e146e4c17bd2ef87711736d587ff8d536dfc','https://bible-api.com/data/cuv/PSA/23/1','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('f8e4ae62-d455-474f-8cfb-0d7b53649dde','en','Yahweh is my shepherd: I shall lack nothing','Psalms 23:1','The opening of Psalm 23, ascribed to David in the superscription.','WEB','na','source_verified','b66d67c885037b034b47734f7547f85da5209489dde851a82d85d414332732a7','Yahweh is my shepherd: I shall lack nothing.','016d705bb7106b35c22ee231916b4f4c2cf00ee7c45132fe39e47a1f47ade8ee','https://bible-api.com/data/web/PSA/23/1','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('968f2304-6d7b-4e00-8c6a-93623f987c7c','21000000-0000-4000-8000-000000000008','10000000-0000-4000-8000-000000000005',NULL,'1Kgs.3.9','prayer',5,19)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('968f2304-6d7b-4e00-8c6a-93623f987c7c','zh-CN','所以求你賜我智慧，可以判斷你的民，能辨別是非','列王纪上 3:9','基遍梦中所求。','CUV-1919','han-traditional','source_verified','c0784e41c81cdbe292eaf5c863c6dd183d1f0ba383112b6cfa9d2d39714f556f','所以求你賜我智慧，可以判斷你的民，能辨別是非。不然，誰能判斷這眾多的民呢？」','7b036b42283c3cf3b68fd703b06b0c2c62a38e4101f69a4244bc803478bb89f9','https://bible-api.com/data/cuv/1KI/3/9','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('968f2304-6d7b-4e00-8c6a-93623f987c7c','en','Give your servant therefore an understanding heart to judge your people, that I may discern between good and evil','1 Kings 3:9','His request in the dream at Gibeon.','WEB','na','source_verified','c2bac548915c8ff60f27b4007cef79a4e8f6b092bcca10295c5221c9cc636a09','Give your servant therefore an understanding heart to judge your people, that I may discern between good and evil; for who is able to judge this great people of yours?”','988cdfc3035b167983e7a2d2a7bec3501086fe81470b22e4ffb9c2f2135c7cb0','https://bible-api.com/data/web/1KI/3/9','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('c2b026b9-9fea-44cf-8f76-7b382c7dc2ff','42000000-0000-4000-8000-000000000036','10000000-0000-4000-8000-000000000005',NULL,'1Kgs.18.21','question',4,20)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('c2b026b9-9fea-44cf-8f76-7b382c7dc2ff','zh-CN','你們心持兩意要到幾時呢','列王纪上 18:21','迦密山上向百姓发问。','CUV-1919','han-traditional','source_verified','f8b0acbc3963d15094a7c2260b6663d7b254c49b3b565982b2064213edbe4d3c','以利亞前來對眾民說：「你們心持兩意要到幾時呢？若耶和華是神，就當順從耶和華；若巴力是神，就當順從巴力。」眾民一言不答。','e666c1882e1d8a2777322f574b5307390ba5581c9b25995799c9c03ce83d9137','https://bible-api.com/data/cuv/1KI/18/21','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('c2b026b9-9fea-44cf-8f76-7b382c7dc2ff','en','How long will you waver between the two sides','1 Kings 18:21','His challenge to the people on Carmel.','WEB','na','source_verified','907efec77a496fc9ae378f9686178adfa180cad531ae798ff1b0f683700a8e3a','Elijah came near to all the people, and said, “How long will you waver between the two sides? If Yahweh is God, follow him; but if Baal, then follow him.” The people didn’t say a word.','3335bead4778e088d0ec71a21b1239e37b90882e15c1261f7bc03d9304b238b9','https://bible-api.com/data/web/1KI/18/21','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('246eb3a3-7a77-4d5b-854f-207274d815b6','42000000-0000-4000-8000-000000000041','10000000-0000-4000-8000-000000000005','62000000-0000-4000-8000-000000000070','Isa.6.8','confession',5,21)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('246eb3a3-7a77-4d5b-854f-207274d815b6','zh-CN','我在這裏，請差遣我','以赛亚书 6:8','圣殿异象中的应答。','CUV-1919','han-traditional','source_verified','70e1c26222a3c54c373b89a01102e904f83dfc5ff6f16430fed25227227a04f4','我又聽見主的聲音說：「我可以差遣誰呢？誰肯為我們去呢？」我說：「我在這裏，請差遣我！」','ef3802ddf07c5878331feb818c438b6d0e5d986d7634c6dd85642d1c95cda688','https://bible-api.com/data/cuv/ISA/6/8','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('246eb3a3-7a77-4d5b-854f-207274d815b6','en','Here I am. Send me','Isaiah 6:8','His answer in the temple vision.','WEB','na','source_verified','8ea7566dd7c60938193831f058aa41b2fc58b434ab746643bf1f7bdbb94cc512','I heard the Lord’s voice, saying, “Whom shall I send, and who will go for us?” Then I said, “Here I am. Send me!”','9c78c40eed29a9edd0028f8e495f4e83ed1f6751e09f24d384928f66627e38c9','https://bible-api.com/data/web/ISA/6/8','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('5094b21d-5fb8-452d-817b-c645131b25e5','42000000-0000-4000-8000-000000000042','10000000-0000-4000-8000-000000000005',NULL,'Jer.1.6','objection',4,22)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('5094b21d-5fb8-452d-817b-c645131b25e5','zh-CN','我不知怎樣說，因為我是年幼的','耶利米书 1:6','受召时的推辞。','CUV-1919','han-traditional','source_verified','3914b6ded4d94677c4e701629fe9bdabe6048a4b98dcea266d1d5257eb44b39d','我就說：主耶和華啊，我不知怎樣說，因為我是年幼的。','2f6977e8776d16140ea4237a908a74a242717f48a48330540508091944066a84','https://bible-api.com/data/cuv/JER/1/6','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('5094b21d-5fb8-452d-817b-c645131b25e5','en','I don’t know how to speak; for I am a child','Jeremiah 1:6','His objection when called.','WEB','na','source_verified','056551d5237ba3130e24d1857283b588a2d8a3a27aac28603dbe30d3deec9f60','Then I said, “Ah, Lord Yahweh! Behold, I don’t know how to speak; for I am a child.”','96d25bdaa92fa5706728abd0a582035203e43c0bac2d8edc989bb623af4aad0a','https://bible-api.com/data/web/JER/1/6','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('984a0b1e-da35-4996-8416-3a9ec5c01124','42000000-0000-4000-8000-000000000044','10000000-0000-4000-8000-000000000005',NULL,'Dan.6.22','declaration',4,23)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('984a0b1e-da35-4996-8416-3a9ec5c01124','zh-CN','我的神差遣使者，封住獅子的口','但以理书 6:22','自狮子坑中回话。','CUV-1919','han-traditional','source_verified','3cf876ef0c362aae24542d289082ab142b7261434aaa3981a20d2df45ee93988','我的神差遣使者，封住獅子的口，叫獅子不傷我；因我在神面前無辜，我在王面前也沒有行過虧損的事。」','54661a033b2e9e97d5b6b6ab46c3affaa7752fd26d409ee8dfbe35b0c671be0c','https://bible-api.com/data/cuv/DAN/6/22','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('984a0b1e-da35-4996-8416-3a9ec5c01124','en','My God has sent his angel, and has shut the lions’ mouths','Daniel 6:22','Called up out of the den.','WEB','na','source_verified','52dc9f5f7da3ac3cb0bb3fbfa6e42e26df715bb6209999bc8799c9be8afca491','My God has sent his angel, and has shut the lions’ mouths, and they have not hurt me; because as before him innocence was found in me; and also before you, O king, I have done no harm.”','ab9242ff4820c66a6bb7e192953b43afc42c0449cddf5b0c1e44de1c6f914018','https://bible-api.com/data/web/DAN/6/22','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('d1e14491-40bc-4004-8483-fd58fd861764','42000000-0000-4000-8000-000000000047','10000000-0000-4000-8000-000000000005',NULL,'Esth.4.16','declaration',5,24)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('d1e14491-40bc-4004-8483-fd58fd861764','zh-CN','我若死就死吧','以斯帖记 4:16','决定进见王之前所说。','CUV-1919','han-traditional','source_verified','3eb9423e14fb1e351273078729a0749c845afd5b02371ea6cad4a205bb7a9b8b','「你當去招聚書珊城所有的猶大人，為我禁食三晝三夜，不喫不喝；我和我的宮女也要這樣禁食。然後我違例進去見王，我若死就死吧！」','cd387a0783435ae51a5580338dd27fabaa0bd791a86a1c39095355d2eb8f13df','https://bible-api.com/data/cuv/EST/4/16','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('d1e14491-40bc-4004-8483-fd58fd861764','en','if I perish, I perish','Esther 4:16','Her decision before going in to the king.','WEB','na','source_verified','1c032f1f2aad1aa72449dd4286ab63a7dc4e889960d5f2fce2e84cc39f15e0fb','“Go, gather together all the Jews who are present in Shushan, and fast for me, and neither eat nor drink three days, night or day. I and my maidens will also fast the same way. Then I will go in to the king, which is against the law; and if I perish, I perish.”','195cece74fa6c67a036d9e848ce9c47b331f34a4ddf10882ff7100ce4e4c3164','https://bible-api.com/data/web/EST/4/16','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('c36c2850-4d97-4d09-8fe6-94faa9b1cd9f','42000000-0000-4000-8000-000000000049','10000000-0000-4000-8000-000000000005',NULL,'Neh.6.3','declaration',4,25)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('c36c2850-4d97-4d09-8fe6-94faa9b1cd9f','zh-CN','我現在辦理大工，不能下去','尼希米记 6:3','拒绝下到阿挪平原赴约。','CUV-1919','han-traditional','source_verified','a0484f922a1fdac2632a903b010c1a460011ce14adfa3591fb3367ecd5d17b2a','於是我差遣人去見他們，說：「我現在辦理大工，不能下去。焉能停工下去見你們呢？」','f16ebdfdc4b5b5fffcf889e3bca677c3a1d3d1de5dccb3bc7165ff30092832ff','https://bible-api.com/data/cuv/NEH/6/3','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('c36c2850-4d97-4d09-8fe6-94faa9b1cd9f','en','I am doing a great work, so that I can’t come down','Nehemiah 6:3','His refusal to come down to the plain of Ono.','WEB','na','source_verified','612d34042f82a02ec531823b17e4945ba07b5e5e991df7c09df41b19e30f4144','I sent messengers to them, saying, “I am doing a great work, so that I can’t come down. Why should the work cease, while I leave it, and come down to you?”','a1e4270f0486df397b2e7e2598a3f8a3fdb4cd2d697c2e5afa3f7a1b40cbffc4','https://bible-api.com/data/web/NEH/6/3','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('11e64759-de19-4908-8a84-aff1148711b5','21000000-0000-4000-8000-000000000009','10000000-0000-4000-8000-000000000005',NULL,'Jonah.2.9','prayer',4,26)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('11e64759-de19-4908-8a84-aff1148711b5','zh-CN','救恩出於耶和華','约拿书 2:9','鱼腹中祷告的结句。','CUV-1919','han-traditional','source_verified','7b40af8a73a40304cee1af1ea1e60395837b1f1ae3cf5bce4ba650d87329376e','但我必用感謝的聲音獻祭與你。我所許的願，我必償還。救恩出於耶和華。','d7130fb6752fc226a8854db00acf3e30466a4e531a44d6bd07be73529627195d','https://bible-api.com/data/cuv/JON/2/9','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('11e64759-de19-4908-8a84-aff1148711b5','en','Salvation belongs to Yahweh','Jonah 2:9','The close of his prayer from the fish.','WEB','na','source_verified','689ee23f009ce56573b7ceda070a88ddbfd41fba1d37ccab751abd99f2e70a35','But I will sacrifice to you with the voice of thanksgiving. I will pay that which I have vowed. Salvation belongs to Yahweh.”','cae9efaca8cf2ba67855c7317d528d7a1241cf4bf093d0e52fc519ae88641467','https://bible-api.com/data/web/JON/2/9','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('637b1789-d90f-4ab9-8ea4-48dcaf8adced','42000000-0000-4000-8000-000000000045','10000000-0000-4000-8000-000000000005',NULL,'Dan.4.30','declaration',3,27)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('637b1789-d90f-4ab9-8ea4-48dcaf8adced','zh-CN','這大巴比倫不是我用大能大力建為京都','但以理书 4:30','在王宫顶上自夸。','CUV-1919','han-traditional','source_verified','256617aa08d3c8f64958cd553b7d9dc43b7ba88382d07f8b65bf94f05b734a4c','他說：「這大巴比倫不是我用大能大力建為京都，要顯我威嚴的榮耀嗎？」','cdccae0a05ed06077ef7262e26f9d771b38bc78dfa5e734f4259b33daed440d0','https://bible-api.com/data/cuv/DAN/4/30','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('637b1789-d90f-4ab9-8ea4-48dcaf8adced','en','Is not this great Babylon, which I have built for the royal dwelling place','Daniel 4:30','Boasting on the roof of his palace.','WEB','na','source_verified','93faef54e2a7f0001453b5b4a6cba3ff469afe5a48795290c5fa526cec162b25','The king spoke and said, “Is not this great Babylon, which I have built for the royal dwelling place, by the might of my power and for the glory of my majesty?”','3c62b7c9b290f19c89af5c25fb7e6bb27c8e3a5ba55c5d69184597d4662e50d3','https://bible-api.com/data/web/DAN/4/30','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('cba78cb9-9a65-4e4a-8a6e-c6a859af2e8b','21000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000005',NULL,'Luke.1.38','confession',5,28)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('cba78cb9-9a65-4e4a-8a6e-c6a859af2e8b','zh-CN','我是主的使女，情願照你的話成就在我身上','路加福音 1:38','报喜叙事中的应答。','CUV-1919','han-traditional','source_verified','c9ef6c0a6613311524d554a86f60f3e9a89fe7fe89c8c218f6e784def78d42bc','馬利亞說：「我是主的使女，情願照你的話成就在我身上。」天使就離開她去了。','c6501dd4cf2932f656a3e47dd8d017e4612cdb542c741d5948f87f6179d63aca','https://bible-api.com/data/cuv/LUK/1/38','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('cba78cb9-9a65-4e4a-8a6e-c6a859af2e8b','en','Behold, the servant of the Lord; let it be done to me according to your word','Luke 1:38','Her answer in the annunciation narrative.','WEB','na','source_verified','de7391b99ab1d1e8885a2b0d99a09d809e2a7c54942be3199198c80026e86dd1','Mary said, “Behold, the servant of the Lord; let it be done to me according to your word.” The angel departed from her.','9c86ee8941269bed1d742ba9ff1f080b2a4986c756b1e15479b908f020ed3740','https://bible-api.com/data/web/LUK/1/38','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('ac915930-8b03-4fc4-843a-dd02e578a35d','21000000-0000-4000-8000-000000000010','10000000-0000-4000-8000-000000000005',NULL,'Luke.1.46','prayer',4,29)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('ac915930-8b03-4fc4-843a-dd02e578a35d','zh-CN','我心尊主為大','路加福音 1:46','尊主颂（Magnificat）的开篇。','CUV-1919','han-traditional','source_verified','5a83399e555e25be8f81b98f55d551999c28d6bd7ff70fe292121ec14ff9839b','馬利亞說：我心尊主為大；','08135d1563dc2957e4ccdd5599f7b06817324abfbaf4ace376f8620bf9de39e3','https://bible-api.com/data/cuv/LUK/1/46','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('ac915930-8b03-4fc4-843a-dd02e578a35d','en','My soul magnifies the Lord','Luke 1:46','The opening of the Magnificat.','WEB','na','source_verified','55c3288ea51c62fcd29f24770d7d4fb80942e12a788b865f8881b10d62f05ab8','Mary said, “My soul magnifies the Lord.','3deb6214e462eff04cef7219328a706dd56c2b50494a3d44e049c708be3d5f24','https://bible-api.com/data/web/LUK/1/46','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('2ebd8c87-c312-40c6-8ca9-dce6b2de8e9b','42000000-0000-4000-8000-000000000051','10000000-0000-4000-8000-000000000005',NULL,'John.1.29','declaration',5,30)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('2ebd8c87-c312-40c6-8ca9-dce6b2de8e9b','zh-CN','看哪，神的羔羊，除去世人罪孽的','约翰福音 1:29','见耶稣走来时所说。和合本在「除去」处附异读〔或作：背負〕。','CUV-1919','han-traditional','source_verified','757a15572541d425ed020ef876761e6a972a04a293ece32d07b12fdf862e4ada','次日，約翰看見耶穌來到他那裏，就說：「看哪，神的羔羊，除去〔或作：背負〕世人罪孽的！','ecb53860172be1fae103e1b3b9f21e314f30814018333a18bdc3e8a0b382cf39','https://bible-api.com/data/cuv/JHN/1/29','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('2ebd8c87-c312-40c6-8ca9-dce6b2de8e9b','en','Behold, the Lamb of God, who takes away the sin of the world','John 1:29','Spoken as he sees Jesus coming toward him. The CUV carries a variant reading at “takes away”.','WEB','na','source_verified','eba318f0e6d23a62af1f36e4494b1f7bd59d347719d53beeb5c621cc5014f13d','The next day, he saw Jesus coming to him, and said, “Behold, the Lamb of God, who takes away the sin of the world!','008b954881e48ce131f39f6aaeae7e5fdccd6e32bcad400d6c325ba108754488','https://bible-api.com/data/web/JHN/1/29','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('446970a2-0e54-4b0e-80a4-2fb788bda2a9','42000000-0000-4000-8000-000000000051','10000000-0000-4000-8000-000000000005',NULL,'John.3.30','declaration',4,31)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('446970a2-0e54-4b0e-80a4-2fb788bda2a9','zh-CN','他必興旺，我必衰微','约翰福音 3:30','门徒问及众人转投耶稣时的回答。','CUV-1919','han-traditional','source_verified','62f0783df556d2593b6ed3d6824355d1c0fd840ea6543935e2ce18111e7d6215','他必興旺，我必衰微。」','058e0e6a026f2b11f36bc7b8cccf11beb5f9c3123022e75946eaa2f3ada30fda','https://bible-api.com/data/cuv/JHN/3/30','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('446970a2-0e54-4b0e-80a4-2fb788bda2a9','en','He must increase, but I must decrease','John 3:30','His reply when his disciples report the crowds leaving.','WEB','na','source_verified','461b4338248af4ca069b658428c3694ae0b1d7c61eec75a1eab8e3c772ed3bc8','He must increase, but I must decrease.','1a292d853327d042d3331f85c2b7816e82903a6391c33b0f49fa26da4bf789de','https://bible-api.com/data/web/JHN/3/30','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('919c22cd-22a2-4701-8eca-053db0850c2e','21000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000005',NULL,'John.14.6','declaration',5,32)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('919c22cd-22a2-4701-8eca-053db0850c2e','zh-CN','我就是道路、真理、生命','约翰福音 14:6','最后晚餐后对门徒所说。','CUV-1919','han-traditional','source_verified','9ec7b2f9a248236f0a60076b20a0b9266fa99a1e058d8d1ca714d60db3988877','耶穌說：「我就是道路、真理、生命；若不藉着我，沒有人能到父那裏去。','19fbdc53710858c9b863d0cade1a78a6cf1c4000d3f531f6638394c5022edc9c','https://bible-api.com/data/cuv/JHN/14/6','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('919c22cd-22a2-4701-8eca-053db0850c2e','en','I am the way, the truth, and the life','John 14:6','Spoken to the disciples after the supper.','WEB','na','source_verified','16e81673d95501d8e92496feeab72d92c81d315c063b3b7d2aaf4c6618fd4c40','Jesus said to him, “I am the way, the truth, and the life. No one comes to the Father, except through me.','d5b1db2cafed05f03e9dcc8969eef8a7e89a2fb88082c3c23652b6d58019209c','https://bible-api.com/data/web/JHN/14/6','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('768953c0-7bb4-4356-8d82-9caad3f71c95','21000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000005','41000000-0000-4000-8000-000000000012','Luke.23.34','prayer',5,33)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('768953c0-7bb4-4356-8d82-9caad3f71c95','zh-CN','父啊！赦免他們；因為他們所作的，他們不曉得','路加福音 23:34','十字架上的祷告。此句在部分最早期抄本中缺，和合本与 WEB 均照印。','CUV-1919','han-traditional','source_verified','7f9780471db8471ed7485fe44fa55246a2def9c752f6172fd77935c64502f696','當下耶穌說：「父啊！赦免他們；因為他們所作的，他們不曉得。」兵丁就拈鬮分他的衣服。','8fb63f57d2c2d2cf70847ee083326a58489f9d43178fac66919af04e9f1d44d8','https://bible-api.com/data/cuv/LUK/23/34','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('768953c0-7bb4-4356-8d82-9caad3f71c95','en','Father, forgive them, for they don’t know what they are doing','Luke 23:34','A prayer from the cross. The sentence is absent from several of the earliest manuscripts; both the CUV and the WEB print it.','WEB','na','source_verified','43208f518c0e37ef9ae76ec3d482bd9d9293fa510a94dff563a7d6ae15b36d83','Jesus said, “Father, forgive them, for they don’t know what they are doing.” Dividing his garments among them, they cast lots.','09fcd48e3e48c91b59bb903c74b24f7a0577b59463c2abe6f1b533810e5dd650','https://bible-api.com/data/web/LUK/23/34','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('278c8faa-ac17-4aa8-8d9f-ca77825a5333','21000000-0000-4000-8000-000000000011','10000000-0000-4000-8000-000000000005',NULL,'Matt.22.37','command',5,34)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('278c8faa-ac17-4aa8-8d9f-ca77825a5333','zh-CN','你要盡心、盡性、盡意愛主你的神','马太福音 22:37','回答哪一条诫命最大。','CUV-1919','han-traditional','source_verified','8e6e08a5a48a4913766d303a9c7bb393b142d959f50ebea7fdf256ab3f8fa25b','耶穌對他說：「你要盡心、盡性、盡意愛主你的神。','e15397b5d2b6da9ba15ac589d284c170504046536314f79484cd3ffb60f1c585','https://bible-api.com/data/cuv/MAT/22/37','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('278c8faa-ac17-4aa8-8d9f-ca77825a5333','en','You shall love the Lord your God with all your heart, with all your soul, and with all your mind','Matthew 22:37','His answer to which commandment is greatest.','WEB','na','source_verified','91b0ecb148e168245596a6bdf282f319ab1965ebf8030e68554fab8dc29ed734','Jesus said to him, “‘You shall love the Lord your God with all your heart, with all your soul, and with all your mind.’','2c4f872bea87840ca2945f96225cb9e9ec15907362e6dc2c887b52ff42ea0513','https://bible-api.com/data/web/MAT/22/37','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('4193d3b6-73eb-447c-80a6-549fe8e4333f','21000000-0000-4000-8000-000000000012','10000000-0000-4000-8000-000000000005',NULL,'Matt.16.16','confession',5,35)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('4193d3b6-73eb-447c-80a6-549fe8e4333f','zh-CN','你是基督，是永生神的兒子','马太福音 16:16','在该撒利亚腓立比境内的回答。','CUV-1919','han-traditional','source_verified','0d0290e874faff264bc638db68c9b66a35b8b8abad1584f4955c56725978b45c','西門彼得回答說：「你是基督，是永生神的兒子。」','ca0b882c508927c517a31852ee42fa628bc3b45bee7c64b9c450d939aa7507de','https://bible-api.com/data/cuv/MAT/16/16','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('4193d3b6-73eb-447c-80a6-549fe8e4333f','en','You are the Christ, the Son of the living God','Matthew 16:16','His answer in the district of Caesarea Philippi.','WEB','na','source_verified','3206c98402ee54a2012018f5095cf097500f9c3d200a0be69239b0b976d5bdf4','Simon Peter answered, “You are the Christ, the Son of the living God.”','b28467b265e7a01b143e46e96ad9d23ca1ce14ea0927601509653d10c937325a','https://bible-api.com/data/web/MAT/16/16','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('d95b64ff-9123-4a04-88a4-dd59ecbd79e4','42000000-0000-4000-8000-000000000055','10000000-0000-4000-8000-000000000005',NULL,'Matt.26.15','question',3,36)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('d95b64ff-9123-4a04-88a4-dd59ecbd79e4','zh-CN','我把他交給你們，你們願意給我多少錢','马太福音 26:15','去见祭司长时所说。','CUV-1919','han-traditional','source_verified','44ce4f7adc561d01b57d23c6ef835e99b6622a0f48b6a593aa8951e5e740cf11','「我把他交給你們，你們願意給我多少錢？」他們就給了他三十塊錢。','179d3ae07a8b8afd79b610398638c823fb5aba616f33f733a988d64ddae60bc6','https://bible-api.com/data/cuv/MAT/26/15','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('d95b64ff-9123-4a04-88a4-dd59ecbd79e4','en','What are you willing to give me, that I should deliver him to you','Matthew 26:15','Spoken when he goes to the chief priests.','WEB','na','source_verified','2661625bc438e6dcae1c06e9c36b6e0bc1edfa279f8e98125e8d9158f4e08b1a','and said, “What are you willing to give me, that I should deliver him to you?” They weighed out for him thirty pieces of silver.','1c01b272923d4e852a25f17869c6599e5233c4011d35856016f70c601708b803','https://bible-api.com/data/web/MAT/26/15','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('06e89778-8093-43b6-8a81-d09ff1253a1b','42000000-0000-4000-8000-000000000056','10000000-0000-4000-8000-000000000005',NULL,'John.18.38','question',3,37)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('06e89778-8093-43b6-8a81-d09ff1253a1b','zh-CN','真理是甚麼呢','约翰福音 18:38','审问中的一问。','CUV-1919','han-traditional','source_verified','b5c44c8f3dd44ffa860fce6cbd56b89dcac02280b7d263a560025d07566d0b68','彼拉多說：「真理是甚麼呢？」說了這話，又出來到猶太人那裏，對他們說：「我查不出他有甚麼罪來。','3b23c3c9af0e28e7f79fd4ed481a4016f8b0010db43fbd5f9c4c6a579d1fd2f3','https://bible-api.com/data/cuv/JHN/18/38','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('06e89778-8093-43b6-8a81-d09ff1253a1b','en','What is truth','John 18:38','A question put during the interrogation.','WEB','na','source_verified','6a343602292cb864a37afc55c4e20be2afee31a336f0de2fa38352bf6406bb73','Pilate said to him, “What is truth?” When he had said this, he went out again to the Jews, and said to them, “I find no basis for a charge against him.','a20d8424a57df32428a3698846973871c64f1f6875e87b4f3a3dafb46b7531db','https://bible-api.com/data/web/JHN/18/38','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('e9c9604e-0eff-4528-8f57-c9b4749ae56c','42000000-0000-4000-8000-000000000052','10000000-0000-4000-8000-000000000005',NULL,'John.20.13','lament',4,38)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('e9c9604e-0eff-4528-8f57-c9b4749ae56c','zh-CN','有人把我主挪了去，我不知道放在那裏','约翰福音 20:13','在空墓旁被问为何哭泣时的回答。','CUV-1919','han-traditional','source_verified','bf0e418f23bb2174f6fce16e960dd7dcf6b23751f8400e87467a571d357abde8','天使對她說：「婦人，你為甚麼哭？」她說：「因為有人把我主挪了去，我不知道放在那裏。」','e32e400c5172469a60a0f6bc6b5d73625e7081f1a701a5804d3f27c6f3c8e3bc','https://bible-api.com/data/cuv/JHN/20/13','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('e9c9604e-0eff-4528-8f57-c9b4749ae56c','en','Because they have taken away my Lord, and I don’t know where they have laid him','John 20:13','Her answer at the empty tomb when asked why she is weeping.','WEB','na','source_verified','a233089f6b1a49b0060af925040a0cc33c7188e6320214a2221a12d0ce222ecf','They told her, “Woman, why are you weeping?” She said to them, “Because they have taken away my Lord, and I don’t know where they have laid him.”','0fb895f1c87bda5c3df63a4dd6ba15d9eed25274ae8d45f2e9b3e464c2a28189','https://bible-api.com/data/web/JHN/20/13','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('c80e0112-d916-47ff-8380-ed7a344ecbaf','21000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000005',NULL,'Gal.2.20','confession',5,39)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('c80e0112-d916-47ff-8380-ed7a344ecbaf','zh-CN','現在活着的不再是我，乃是基督在我裏面活着','加拉太书 2:20','加拉太书中自述。','CUV-1919','han-traditional','source_verified','fce14e952149a7bb4bc206a796d71a9ef5668f8889a18d3d152401100cafb6d8','我已經與基督同釘十字架，現在活着的不再是我，乃是基督在我裏面活着；並且我如今在肉身活着，是因信神的兒子而活；他是愛我，為我捨己。','1817d292e049b8d54b151f3787d8141ad1647e095a503ecb8b490054d86ccd5c','https://bible-api.com/data/cuv/GAL/2/20','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('c80e0112-d916-47ff-8380-ed7a344ecbaf','en','it is no longer I that live, but Christ lives in me','Galatians 2:20','From his own account in Galatians.','WEB','na','source_verified','7cdaaab18caba8c8711982d2b8c0eee589ee12401ae2394b3b082f3f2fc91128','I have been crucified with Christ, and it is no longer I that live, but Christ lives in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me, and gave himself up for me.','3ef986cd54057d54011139d6f32b5779025e37f91c662881445ec9946dc1e083','https://bible-api.com/data/web/GAL/2/20','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('d6ba143e-fe2e-4ea8-8b43-900fc108837a','21000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000005',NULL,'1Cor.13.13','declaration',5,40)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('d6ba143e-fe2e-4ea8-8b43-900fc108837a','zh-CN','其中最大的是愛','哥林多前书 13:13','哥林多前书第十三章的结句。','CUV-1919','han-traditional','source_verified','2dfb1ae5743979c9f06b62c083b05e6d368cbf70ce466897a8c6d09cf75cbdcc','如今常存的有信，有望，有愛，這三樣，其中最大的是愛。','03a8a27d5e8a9b4e79f6e8002651f788bf0bf18f0462a666046eb470a38ff265','https://bible-api.com/data/cuv/1CO/13/13','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('d6ba143e-fe2e-4ea8-8b43-900fc108837a','en','The greatest of these is love','1 Corinthians 13:13','The close of 1 Corinthians 13.','WEB','na','source_verified','df44f68ba5e8d0a15d8ac12b4d9a7fdc824a4ed2df00d2876ece5e2465aa4a86','But now faith, hope, and love remain—these three. The greatest of these is love.','61e8fff078e8b1d2ad00d107bf81b007d419f223bd90421e4ea11def2b844f98','https://bible-api.com/data/web/1CO/13/13','2026-08-18T00:00:00Z'::timestamptz,'published')
INSERT INTO character_quotes(id,character_id,work_id,event_id,osis_ref,speech_kind,importance,sort_order) VALUES
  ('a2b40747-9bd9-4780-84ae-e8379826bf26','21000000-0000-4000-8000-000000000013','10000000-0000-4000-8000-000000000005',NULL,'2Tim.4.7','declaration',4,41)
INSERT INTO character_quote_translations(quote_id,locale,quote_text,reference_label,context_note,translation_edition,script_variant,text_status,text_sha256,source_verse_text,source_verse_sha256,verified_source_url,verified_at,status) VALUES
  ('a2b40747-9bd9-4780-84ae-e8379826bf26','zh-CN','那美好的仗我已經打過了，當跑的路我已經跑盡了，所信的道我已經守住了','提摩太后书 4:7','书信末尾的回顾。','CUV-1919','han-traditional','source_verified','35d1c89c526207332aa81868f01a4a323d343fe5f902ea111ee0c99eb09cc79c','那美好的仗我已經打過了，當跑的路我已經跑盡了，所信的道我已經守住了。','3e23a243ec159897a0c3b8c53feddd007b928b1ae61f477b13856fc5d04b3020','https://bible-api.com/data/cuv/2TI/4/7','2026-08-18T00:00:00Z'::timestamptz,'published'),
  ('a2b40747-9bd9-4780-84ae-e8379826bf26','en','I have fought the good fight. I have finished the course. I have kept the faith','2 Timothy 4:7','A retrospect near the end of the letter.','WEB','na','source_verified','5d6325a67b9676995ed3c8a034e32de5c586043587d7f5a64ea0c71ae25b7e39','I have fought the good fight. I have finished the course. I have kept the faith.','51d2eaa571af90aa647ca5100af700eca2c45c1a949c38eaef36475776bd5c0e','https://bible-api.com/data/web/2TI/4/7','2026-08-18T00:00:00Z'::timestamptz,'published')
